={{ (() => {
  const qr = $json.quick_replies || [];
  if (qr.length > 0) {
    return JSON.stringify({
      recipient: { id: $json.sender_id },
      message: {
        text: $json.reply,
        quick_replies: qr.slice(0,13).map(t => ({
          content_type: 'text',
          title: t.slice(0,20),
          payload: t.toUpperCase().replace(/[^A-Z0-9]/g,'_')
        }))
      }
    });
  }
  return JSON.stringify({
    recipient: { id: $json.sender_id },
    message: { text: $json.reply }
  });
})() }}
